frame.store("_a_diet_predicate", { let __signature_3108 = Signature { name: "_a_diet_predicate".into(), positional: vec!["who".into(),"diet".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_3110 = Value::dict(); __attrs_3110.dict_set(Value::from("__doc__"), Value::from("A person's diet as the words after their name: \"eats fish\", \"doesn't eat meat\", \"is vegan\".\n\n    The store keeps a restriction as \"no fish\", and what somebody eats put back as \"eats fish\":\n    a take-back of a restriction is not an empty record, it is the food they eat now, so the\n    recall says \"Your son eats fish.\" where \"Your son is eats fish.\" is not a sentence.\n    "))?; __attrs_3110.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_3111 = Value::dict(); __attrs_3110.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_3107 = Frame::module(frame.globals.clone()); let mut __function_3109 = NativeFunction::qualified_with_origin("_a_diet_predicate".into(), "_a_diet_predicate".into(), "bot.memory.store_replies".into(), __attrs_3110, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/memory/store_replies.py", first: 6369, last: 6383, qualname: "_a_diet_predicate" }, closure: __closure_3107.clone(), freevars: vec![] }, move |rt, args| __py_193::_a_diet_predicate(rt, __closure_3107.clone(), &__signature_3108, args)); __function_3109 })?;
frame.store("_their_pronoun", { let __signature_3113 = Signature { name: "_their_pronoun".into(), positional: vec!["who".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_3115 = Value::dict(); __attrs_3115.dict_set(Value::from("__doc__"), Value::from("The word for the person in the second half of a sentence: \"for her\", \"for them\".\n\n    A word that is in both lists is a person either way - a mate, a friend, a colleague, a\n    flatmate - and `SHE` was read first, so \"my mate is teetotal\" then \"what can he have\" ended\n    \"that's all I have on food for her\". A word that says nothing about which it is says \"them\".\n    "))?; __attrs_3115.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_3116 = Value::dict(); __attrs_3115.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_3112 = Frame::module(frame.globals.clone()); let mut __function_3114 = NativeFunction::qualified_with_origin("_their_pronoun".into(), "_their_pronoun".into(), "bot.memory.store_replies".into(), __attrs_3115, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/memory/store_replies.py", first: 6385, last: 6398, qualname: "_their_pronoun" }, closure: __closure_3112.clone(), freevars: vec![] }, move |rt, args| __py_194::_their_pronoun(rt, __closure_3112.clone(), &__signature_3113, args)); __function_3114 })?;
frame.store("_no_diet", { let __signature_3118 = Signature { name: "_no_diet".into(), positional: vec!["who".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_3120 = Value::dict(); __attrs_3120.dict_set(Value::from("__doc__"), Value::from("An ask about how someone else eats when nothing food-shaped is kept for them.\n\n    Saying \"you haven't told me what your dad eats\" on its own is true and cold, and it is what\n    someone with a diabetic dad gets. The offer is the part that helps: the fact is one line away.\n\n    A baby is left to the weaning answers: the store keeps the age, and \"my baby is 7 months what\n    can she eat\" is a question about that age, not about a diet the store has never heard.\n    "))?; __attrs_3120.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_3121 = Value::dict(); __attrs_3120.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_3117 = Frame::module(frame.globals.clone()); let mut __function_3119 = NativeFunction::qualified_with_origin("_no_diet".into(), "_no_diet".into(), "bot.memory.store_replies".into(), __attrs_3120, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/memory/store_replies.py", first: 6400, last: 6412, qualname: "_no_diet" }, closure: __closure_3117.clone(), freevars: vec![] }, move |rt, args| __py_195::_no_diet(rt, __closure_3117.clone(), &__signature_3118, args)); __function_3119 })?;
