frame.store("_both_food_facts", { let __signature_3128 = Signature { name: "_both_food_facts".into(), positional: vec!["who".into(),"allergies".into(),"diet".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_3130 = Value::dict(); __attrs_3130.dict_set(Value::from("__doc__"), Value::from("An allergy and a diet kept for the same person, said in one answer.\n\n    A line can carry both - \"my mum is allergic to nuts and she doesnt eat meat\" - and the ask\n    that follows (\"what can my mum eat\") used to be answered with the diet alone, because a diet\n    kept for a person answers before the allergy does. The allergy is the fact that could hurt\n    them, so it goes first and the diet follows it rather than replacing it.\n    "))?; __attrs_3130.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_3131 = Value::dict(); __attrs_3130.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_3127 = Frame::module(frame.globals.clone()); let mut __function_3129 = NativeFunction::qualified_with_origin("_both_food_facts".into(), "_both_food_facts".into(), "bot.memory.store_replies".into(), __attrs_3130, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/memory/store_replies.py", first: 6423, last: 6439, qualname: "_both_food_facts" }, closure: __closure_3127.clone(), freevars: vec![] }, move |rt, args| __py_197::_both_food_facts(rt, __closure_3127.clone(), &__signature_3128, args)); __function_3129 })?;
