frame.store("_what_the_food_has", { let __signature_3140 = Signature { name: "_what_the_food_has".into(), positional: vec!["low".into(),"ruled".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_3142 = Value::dict(); __attrs_3142.dict_set(Value::from("__doc__"), Value::from("The food the line names, when it is a thing the person cannot have: (\"cheese\", \"dairy\").\n\n    \"can he have cheese\" after \"my husband is lactose intolerant\" is answered about the cheese,\n    not only about dairy in general: a person asking about one food has that food in their hand.\n    Only an everyday food that is that thing every time it is eaten is named, so nothing is\n    claimed about a dish the store was not told the recipe of; and a food that is the ruled-out\n    thing itself (\"what about eggs\" of a vegan's eggs) is left to the sentence that names it.\n    "))?; __attrs_3142.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_3143 = Value::dict(); __attrs_3142.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_3139 = Frame::module(frame.globals.clone()); let mut __function_3141 = NativeFunction::qualified_with_origin("_what_the_food_has".into(), "_what_the_food_has".into(), "bot.memory.store_replies".into(), __attrs_3142, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/memory/store_replies.py", first: 6467, last: 6489, qualname: "_what_the_food_has" }, closure: __closure_3139.clone(), freevars: vec![] }, move |rt, args| __py_199::_what_the_food_has(rt, __closure_3139.clone(), &__signature_3140, args)); __function_3141 })?;
frame.store("_diet_is_their_food", { let __default_3147 = Value::from(""); let __default_3148 = Value::Bool(false); let __signature_3145 = Signature { name: "_diet_is_their_food".into(), positional: vec!["who".into(),"diet".into(),"low".into(),"plain".into()], positional_only: 0, defaults: vec![__default_3147,__default_3148], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_3149 = Value::dict(); __attrs_3149.dict_set(Value::from("__doc__"), Value::from("What a person cannot have, from the diet kept for them, or None when the diet says it.\n\n    \"my wife is vegetarian\" then \"what cant she have\" is the ask the allergy answer already\n    works out, and with the diet kept the store can still say what it rules out. Only a named\n    diet is read this way, so nothing is claimed about food the store was not told.\n    "))?; __attrs_3149.dict_set(Value::from("__defaults__"), Value::tuple(__signature_3145.defaults.clone()))?; let __kwdefaults_3150 = Value::dict(); __attrs_3149.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_3144 = Frame::module(frame.globals.clone()); let mut __function_3146 = NativeFunction::qualified_with_origin("_diet_is_their_food".into(), "_diet_is_their_food".into(), "bot.memory.store_replies".into(), __attrs_3149, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/memory/store_replies.py", first: 6491, last: 6519, qualname: "_diet_is_their_food" }, closure: __closure_3144.clone(), freevars: vec![] }, move |rt, args| __py_200::_diet_is_their_food(rt, __closure_3144.clone(), &__signature_3145, args)); __function_3146 })?;
